package com.school.enrollment;
import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame {
 private final JTextField username=new JTextField("admin",18);private final JPasswordField password=new JPasswordField(18);
 public LoginFrame(){setTitle("Student Enrollment System - Login");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(420,260);setLocationRelativeTo(null);JPanel root=new JPanel(new GridBagLayout());root.setBorder(BorderFactory.createEmptyBorder(20,25,20,25));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(7,7,7,7);g.fill=GridBagConstraints.HORIZONTAL;JLabel title=new JLabel("Student Enrollment System",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,20f));g.gridx=0;g.gridy=0;g.gridwidth=2;root.add(title,g);g.gridwidth=1;g.gridy++;g.gridx=0;root.add(new JLabel("Username"),g);g.gridx=1;root.add(username,g);g.gridy++;g.gridx=0;root.add(new JLabel("Password"),g);g.gridx=1;root.add(password,g);JButton login=new JButton("Sign in");login.addActionListener(e->signIn());g.gridy++;g.gridx=0;g.gridwidth=2;root.add(login,g);add(root);getRootPane().setDefaultButton(login);}
 private void signIn(){try{String u=username.getText().trim();if(Auth.login(u,password.getPassword())){String[] row=Database.query("SELECT ID,FULL_NAME,ROLE_NAME FROM APP_USERS WHERE USERNAME=? AND ACTIVE=1",u).get(0);dispose();new DashboardFrame(row[1],row[2],Integer.parseInt(row[0])).setVisible(true);}else JOptionPane.showMessageDialog(this,"Incorrect username or password.");}catch(Exception ex){JOptionPane.showMessageDialog(this,"Login error: "+ex.getMessage());}}
}
